&__preview {
  position: fixed;
  top: 50%;
  left: fluid(24, 56);
  transform: translateY(-50%);
  width: fluid(200, 320);
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-md, 12px);
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  clip-path: inset(50% 0 50% 0 round var(--radius-md, 12px));
  transition:
    opacity 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    visibility 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    clip-path 0.48s cubic-bezier(0.76, 0, 0.24, 1);
  z-index: 100;

  &.is-visible {
    opacity: 1;
    visibility: visible;
    clip-path: inset(0% 0 0% 0 round var(--radius-md, 12px));
  }

  &.is-visible.is-switching {
    clip-path: inset(50% 0 50% 0 round var(--radius-md, 12px));
  }

  &.is-closing {
    opacity: 0;
    clip-path: inset(50% 0 50% 0 round var(--radius-md, 12px));
  }
}

