file.content:
@use "../abstract" as *;

@keyframes no-loop-filter-rect-pulse {
  0%,
  18%,
  100% {
    opacity: 0.16;
  }

  30%,
  48% {
    opacity: 1;
  }
}

.no-loop-filter-rect {
  --loop-filter-delay-base: 0s;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0;
  flex-shrink: 0;

  span {
    width: fluid(3, 5);
    height: fluid(3, 5);
    background: currentColor;
    opacity: 0.16;
    animation: no-loop-filter-rect-pulse 1.2s linear infinite;
  }

  span:nth-child(1) {
    animation-delay: calc(var(--loop-filter-delay-base) + 0s);
  }

  span:nth-child(2) {
    animation-delay: calc(var(--loop-filter-delay-base) + 0.18s);
  }

  span:nth-child(3) {
    animation-delay: calc(var(--loop-filter-delay-base) + 0.54s);
  }

  span:nth-child(4) {
    animation-delay: calc(var(--loop-filter-delay-base) + 0.36s);
  }

  @media (prefers-reduced-motion: reduce) {
    span {
      animation: none;
      opacity: 1;
    }
  }
}

