&__skill-list:has(&__skill-item:hover) &__skill-item:not(:hover) {
  opacity: 0.2;
}

&__skill-label {
  display: block;
  line-height: 1;
}

&__skill-desc {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  margin: 0;
  opacity: 0;
  transition: opacity 0.24s ease;
  white-space: nowrap;
}

&__skill-item:hover &__skill-desc {
  opacity: 0.64;
}
